644: function parseBlocker(value: unknown, candidateIds: ReadonlySet<string>): PivotSeatBlocker | null {
645:   if (!isRecord(value)) {
646:     return null;
647:   }
648:   if (value.severity !== 'low' && value.severity !== 'medium' && value.severity !== 'high') {
649:     return null;
650:   }
651:   if (typeof value.message !== 'string' || value.message.trim() === '') {
652:     return null;
653:   }
654:   if (value.candidateId !== undefined
655:     && (typeof value.candidateId !== 'string' || !candidateIds.has(value.candidateId))) {
656:     return null;
657:   }
658:   return {
659:     severity: value.severity,
660:     message: value.message.trim(),
661:     ...(typeof value.candidateId === 'string' ? { candidateId: value.candidateId } : {}),
662:   };
663: }
