668:     ? JSON.stringify(event.report, null, 2)
669:     : JSON.stringify({ error: event.error ?? event.parseError ?? 'Unknown seat failure' }, null, 2);
670:   return [
671:     `# ${String(event.seatId)}`,
672:     '',
673:     `- Status: ${status}`,
674:     `- Parse valid: ${String(event.parseValid === true)}`,
675:     `- Mandate: ${String(event.mandate)}`,
676:     '',
677:     '## Durable Result',
678:     '',
679:     '```json',
680:     body,
681:     '```',
682:     '',
