716: function quorumFromSeatEvents(events: readonly PivotEvent[]): PivotQuorumResult {
717:   const fulfilled = events.filter((event) => event.status === 'fulfilled').length;
718:   const parseValid = events.filter((event) => event.parseValid === true).length;
719:   return {
720:     required: 3,
721:     returned: events.length,
722:     fulfilled,
723:     parseValid,
724:     allFailed: events.length === 3 && fulfilled === 0,
725:     passed: events.length === 3 && fulfilled === 3 && parseValid === 3,
726:   };
