729: function failureReasonForQuorum(quorum: PivotQuorumResult): PivotFailureReason {
730:   if (quorum.allFailed) {
731:     return 'council_all_seats_rejected';
732:   }
733:   if (quorum.fulfilled < 3) {
734:     return 'council_return_quorum_failed';
735:   }
736:   return 'council_parse_quorum_failed';
737: }
