739: function preflightFailure(
740:   config: NormalizedDivergentConfig,
741:   usage: PivotUsage,
742:   openingAttempt: boolean,
743: ): PivotFailureReason | null {
744:   if (usage.completedPivots >= config.maxPivots) {
745:     return 'max_pivots_exceeded';
746:   }
747:   // The cap bounds one council attempt. An attempt holds no seat outputs when it opens,
748:   // and a resumed attempt already passed this check when it opened.
749:   if (openingAttempt && 3 > config.maxCouncilSeatOutputs) {
750:     return 'max_council_seat_outputs_exceeded';
751:   }
752:   return null;
