816: /** Build and validate the isolated artifact paths for one pivot Council transaction. */
817: export function buildPivotCouncilPaths(
818:   artifactRoot: string,
819:   pivotId: string,
820:   attempt: PivotAttempt = 1,
821: ): PivotCouncilPaths {
822:   if (attempt !== 1 && attempt !== 2) {
823:     throw new TypeError('attempt must be 1 or 2.');
824:   }
825:   const rootInput = nonEmptyString(artifactRoot, 'artifactRoot');
826:   if (!/^pivot-[1-9][0-9]*-[a-f0-9]{12}$/u.test(pivotId)) {
827:     throw new TypeError('pivotId must match pivot-<ordinal>-<12 lowercase hex characters>.');
828:   }
829:   const canonicalRoot = resolveProspectiveRealPath(rootInput);
830:   if (pathContainsAiCouncil(canonicalRoot)) {
831:     throw new TypeError('artifactRoot must not be inside an ai-council artifact tree.');
832:   }
833:   const pivotRoot = join(canonicalRoot, 'divergent', 'pivots', pivotId);
834:   const councilRoot = join(pivotRoot, 'council');
835:   const attemptRoot = attempt === 2 ? join(councilRoot, 'attempt-2') : councilRoot;
836:   const seatsRoot = join(attemptRoot, 'seats');
837:   return {
838:     artifactRoot: canonicalRoot,
839:     pivotRoot,
840:     councilRoot,
841:     configPath: join(councilRoot, 'config.json'),
842:     statePath: join(councilRoot, 'state.jsonl'),
843:     seatsRoot,
844:     seatPaths: [
845:       join(seatsRoot, 'seat-001.md'),
846:       join(seatsRoot, 'seat-002.md'),
847:       join(seatsRoot, 'seat-003.md'),
848:     ],
849:     deliberationPath: join(attemptRoot, 'deliberation.md'),
850:     reportPath: join(councilRoot, 'report.md'),
851:   };
852: }
