854: /** Parse and validate an injected seat output without accepting partial reports. */
855: export function parsePivotSeatReport(
856:   output: unknown,
857:   expectedSeatId: string,
858:   candidateIds: ReadonlySet<string>,
859: ): PivotSeatReportParseResult {
860:   let parsed = output;
861:   if (typeof parsed === 'string') {
862:     try {
863:       parsed = JSON.parse(parsed);
864:     } catch {
865:       return { valid: false, reason: 'Seat output must be a JSON object or JSON object string.' };
866:     }
867:   }
868:   if (!isRecord(parsed)) {
869:     return { valid: false, reason: 'Seat output must be an object.' };
870:   }
871:   if (parsed.seatId !== expectedSeatId) {
872:     return { valid: false, reason: `Seat report must identify itself as "${expectedSeatId}".` };
873:   }
874:   const selectedCandidateId = parsed.selectedCandidateId;
875:   if (selectedCandidateId !== null
876:     && (typeof selectedCandidateId !== 'string' || !candidateIds.has(selectedCandidateId))) {
877:     return { valid: false, reason: 'selectedCandidateId must be null or identify a valid candidate.' };
878:   }
879:   if (typeof parsed.materialEndorsement !== 'boolean') {
880:     return { valid: false, reason: 'materialEndorsement must be a boolean.' };
881:   }
882:   if (parsed.materialEndorsement && selectedCandidateId === null) {
883:     return { valid: false, reason: 'A material endorsement must identify a selected candidate.' };
884:   }
885:   if (typeof parsed.rationale !== 'string' || parsed.rationale.trim() === '') {
886:     return { valid: false, reason: 'Seat rationale must be a non-empty string.' };
887:   }
888:   if (!Array.isArray(parsed.blockers)) {
889:     return { valid: false, reason: 'Seat blockers must be an array.' };
890:   }
891:   const blockers = parsed.blockers.map((blocker) => parseBlocker(blocker, candidateIds));
892:   if (blockers.some((blocker) => blocker === null)) {
893:     return { valid: false, reason: 'Every seat blocker must match the blocker contract.' };
894:   }
895:   return {
896:     valid: true,
897:     report: {
898:       seatId: expectedSeatId,
899:       selectedCandidateId: selectedCandidateId as string | null,
900:       materialEndorsement: parsed.materialEndorsement,
901:       rationale: parsed.rationale.trim(),
902:       blockers: blockers as PivotSeatBlocker[],
903:     },
904:   };
905: }
906: 
907: /** Evaluate two-of-three material endorsement and the global high-blocker veto. */
908: export function evaluatePivotAgreement(
909:   reports: readonly PivotSeatReport[],
910:   candidateOrder: readonly string[],
911: ): PivotAgreementResult {
912:   const highSeverityBlockers = reports.flatMap((report) =>
913:     report.blockers.filter((blocker) => blocker.severity === 'high'));
914:   const tallies = candidateOrder.map((candidateId) => {
915:     const endorsingSeatIds = reports
916:       .filter((report) => report.materialEndorsement && report.selectedCandidateId === candidateId)
917:       .map((report) => report.seatId);
918:     return { candidateId, endorsementCount: endorsingSeatIds.length, endorsingSeatIds };
919:   });
920:   const selected = tallies.find((tally) => tally.endorsementCount >= 2) ?? null;
921:   const converged = reports.length === 3 && selected !== null && highSeverityBlockers.length === 0;
922:   return {
923:     converged,
924:     selectedCandidateId: selected?.candidateId ?? null,
925:     endorsementCount: selected?.endorsementCount ?? 0,
926:     endorsingSeatIds: selected?.endorsingSeatIds ?? [],
927:     tallies,
928:     highSeverityBlockers,
929:     reason: highSeverityBlockers.length > 0
930:       ? 'high_severity_blocker'
931:       : selected === null
932:         ? 'insufficient_endorsement'
933:         : 'agreed',
934:   };
935: }
