937: // ───────────────────────────────────────────────────────────────────
938: // 5. TRANSACTION — PREPARE / RECORD / FINALIZE
939: // ───────────────────────────────────────────────────────────────────
940: //
941: // runDivergentPivot works only when the caller can hand it a synchronous,
942: // in-process dispatchSeat callback. A YAML-interpreted workflow cannot:
943: // only the running agent can natively dispatch a Council seat, and a
944: // single script invocation cannot pause mid-run for that and resume with
945: // the result. The three functions below split the same transaction across
946: // process boundaries — prepare persists everything up through "which seats
947: // are still missing" and returns; recordPivotSeatResult durably records
948: // one externally-obtained seat result per call (one per native dispatch
949: // step); finalize re-derives all context from disk (via the durable
950: // config.json prepare already wrote) and completes the transaction.
951: // runDivergentPivot composes all three for callers that do have a working
952: // synchronous dispatchSeat, so its observable behavior is unchanged.
953: 
954: export interface PivotPendingResult {
955:   readonly status: 'pending';
956:   readonly pivotId: string;
957:   readonly paths: PivotCouncilPaths;
958:   readonly resumed: boolean;
959:   readonly attempt: PivotAttempt;
960:   readonly missingSeats: readonly PivotSeatMandate[];
961:   readonly dispatchContext: PivotDispatchContext;
962: }
963: 
964: export type PivotPrepareResult = PivotCompletedResult | PivotFailedResult | PivotPendingResult;
965: 
966: export interface PreparePivotTransactionOptions {
967:   readonly artifactRoot: string;
968:   readonly identity: PivotIdentityInput;
969:   readonly config?: PivotConfigInput;
970:   readonly usage: PivotUsage;
971:   readonly seats: readonly PivotSeatMandate[];
972:   readonly candidates: readonly unknown[];
973:   readonly priorCandidates?: readonly unknown[];
974:   readonly previousFocus: string;
975:   readonly saturatedDirections?: readonly string[];
976:   readonly now?: () => Date | string;
977:   readonly afterEventPersisted?: PivotEventObserver;
978: }
979: 
980: export type PivotSeatDispatchOutcome =
981:   | {
982:     readonly status: 'fulfilled';
983:     readonly output: unknown;
984:     readonly startedAtIso: string;
985:     readonly completedAtIso: string;
986:     readonly durationMs: number;
987:   }
988:   | {
989:     readonly status: 'rejected';
990:     readonly error?: { readonly name: string; readonly message: string };
991:     readonly startedAtIso: string;
