1013: interface PersistedPivotConfig {
1014:   readonly schemaVersion: 1;
1015:   readonly pivotId: string;
1016:   readonly identity: PivotIdentityInput;
1017:   readonly attempt: PivotAttempt;
1018:   readonly invariants: { readonly rounds: PivotAttempt; readonly seats: 3; readonly depth: 1; readonly recursionAllowed: false };
1019:   readonly limits: NormalizedDivergentConfig;
1020:   readonly usageAtStart: PivotUsage;
1021:   readonly seats: readonly PivotSeatMandate[];
1022:   readonly acceptedCandidates: readonly PivotCandidate[];
1023:   readonly rejectedCandidates: readonly RejectedPivotCandidateDeduplication[];
1024:   readonly previousFocus: string;
1025:   readonly saturatedDirections: readonly string[];
1026: }
1027: 
1028: function parsePersistedIdentity(value: unknown): PivotIdentityInput {
1029:   if (!isRecord(value)) throw new Error('Persisted pivot identity must be an object.');
1030:   const generation = typeof value.generation === 'number'
1031:     ? String(nonNegativeInteger(value.generation, 'identity.generation'))
1032:     : nonEmptyString(value.generation, 'identity.generation');
1033:   return {
1034:     sessionId: nonEmptyString(value.sessionId, 'identity.sessionId'),
1035:     generation,
1036:     loopType: nonEmptyString(value.loopType, 'identity.loopType'),
1037:     sourceIteration: nonNegativeInteger(value.sourceIteration, 'identity.sourceIteration'),
1038:     normalizedTrigger: normalizeTrigger(nonEmptyString(value.normalizedTrigger, 'identity.normalizedTrigger')),
1039:     ordinal: positiveInteger(value.ordinal, 'identity.ordinal'),
1040:   };
1041: }
1042: 
1043: function parsePersistedLimits(value: unknown): NormalizedDivergentConfig {
1044:   if (!isRecord(value)) throw new Error('Persisted pivot limits must be an object.');
1045:   const required = ['maxPivots', 'maxCouncilSeatOutputs', 'minRemainingIterations', 'candidateSimilarityThreshold'];
1046:   if (required.some((key) => !Object.prototype.hasOwnProperty.call(value, key))) {
1047:     throw new Error('Persisted pivot limits are incomplete.');
1048:   }
1049:   return {
1050:     maxPivots: positiveInteger(value.maxPivots, 'limits.maxPivots'),
1051:     maxCouncilSeatOutputs: positiveInteger(value.maxCouncilSeatOutputs, 'limits.maxCouncilSeatOutputs'),
1052:     minRemainingIterations: nonNegativeInteger(value.minRemainingIterations, 'limits.minRemainingIterations'),
1053:     candidateSimilarityThreshold: finiteRatio(value.candidateSimilarityThreshold, 'limits.candidateSimilarityThreshold'),
1054:   };
1055: }
1056: 
1057: function parsePersistedUsage(value: unknown): PivotUsage {
1058:   if (!isRecord(value)) throw new Error('Persisted pivot usage must be an object.');
1059:   return {
1060:     completedPivots: nonNegativeInteger(value.completedPivots, 'usageAtStart.completedPivots'),
1061:     councilSeatOutputs: nonNegativeInteger(value.councilSeatOutputs, 'usageAtStart.councilSeatOutputs'),
1062:     remainingIterations: nonNegativeInteger(value.remainingIterations, 'usageAtStart.remainingIterations'),
1063:     insidePivot: value.insidePivot === true,
1064:   };
1065: }
1066: 
1067: function parsePersistedSeats(value: unknown): readonly PivotSeatMandate[] {
1068:   if (!Array.isArray(value)) throw new Error('Persisted pivot seats must be an array.');
1069:   return normalizeSeats(value.map((seat, index) => {
1070:     if (!isRecord(seat)) throw new Error(`Persisted seat at index ${index} must be an object.`);
1071:     return {
1072:       id: nonEmptyString(seat.id, `seats[${index}].id`),
1073:       mandate: nonEmptyString(seat.mandate, `seats[${index}].mandate`),
1074:     };
1075:   }));
1076: }
1077: 
1078: function parsePersistedCandidates(value: unknown, field: string): readonly PivotCandidate[] {
1079:   if (!Array.isArray(value)) throw new Error(`Persisted ${field} must be an array.`);
1080:   return value.map((candidate, index) => {
1081:     const validation = validatePivotCandidate(candidate);
1082:     if (!validation.valid) {
1083:       throw new Error(`Persisted ${field}[${index}] is not a valid pivot candidate.`);
1084:     }
1085:     return validation.candidate;
1086:   });
1087: }
1088: 
1089: function parsePersistedRejectedCandidates(value: unknown): readonly RejectedPivotCandidateDeduplication[] {
1090:   if (!Array.isArray(value)) throw new Error('Persisted rejectedCandidates must be an array.');
1091:   return value.map((entry, index) => {
1092:     if (!isRecord(entry)
1093:       || entry.accepted !== false
1094:       || typeof entry.maxSimilarity !== 'number'
1095:       || !Number.isFinite(entry.maxSimilarity)
1096:       || entry.maxSimilarity < 0
1097:       || entry.maxSimilarity > 1
1098:       || !Array.isArray(entry.rejections)) {
1099:       throw new Error(`Persisted rejectedCandidates[${index}] is invalid.`);
1100:     }
1101:     const rejections = entry.rejections.map((rejection, rejectionIndex) => {
1102:       if (!isRecord(rejection)
1103:         || typeof rejection.code !== 'string'
1104:         || typeof rejection.message !== 'string'
1105:         || rejection.message.trim() === '') {
1106:         throw new Error(`Persisted rejectedCandidates[${index}].rejections[${rejectionIndex}] is invalid.`);
1107:       }
1108:       const code = rejection.code;
1109:       if (code !== 'invalid_candidate'
1110:         && code !== 'invalid_prior_candidate'
1111:         && code !== 'duplicate_id'
1112:         && code !== 'exact_duplicate'
1113:         && code !== 'materially_similar') {
1114:         throw new Error(`Persisted rejectedCandidates[${index}] has an unknown rejection code.`);
1115:       }
1116:       if (rejection.similarity !== undefined
1117:         && (typeof rejection.similarity !== 'number'
1118:           || !Number.isFinite(rejection.similarity)
1119:           || rejection.similarity < 0
1120:           || rejection.similarity > 1)) {
1121:         throw new Error(`Persisted rejectedCandidates[${index}] has an invalid similarity.`);
1122:       }
1123:       const parsed: RejectedPivotCandidateDeduplication['rejections'][number] = {
1124:         code,
1125:         message: rejection.message.trim(),
1126:         ...(typeof rejection.field === 'string' ? { field: rejection.field } : {}),
1127:         ...(typeof rejection.priorCandidateId === 'string' ? { priorCandidateId: rejection.priorCandidateId } : {}),
1128:         ...(typeof rejection.similarity === 'number' && Number.isFinite(rejection.similarity)
1129:           ? { similarity: rejection.similarity }
1130:           : {}),
1131:       };
1132:       return parsed;
1133:     });
1134:     const candidate = entry.candidate === undefined ? undefined : parsePersistedCandidates([entry.candidate], 'candidate')[0];
1135:     const normalizedFingerprint = entry.normalizedFingerprint;
1136:     if (normalizedFingerprint !== undefined
1137:       && (typeof normalizedFingerprint !== 'string' || normalizedFingerprint.trim() === '')) {
1138:       throw new Error(`Persisted rejectedCandidates[${index}] has an invalid fingerprint.`);
1139:     }
1140:     return {
1141:       accepted: false,
1142:       maxSimilarity: entry.maxSimilarity,
1143:       rejections,
1144:       ...(candidate ? { candidate } : {}),
1145:       ...(typeof normalizedFingerprint === 'string' ? { normalizedFingerprint } : {}),
1146:     };
1147:   });
1148: }
1149: 
1150: function parsePersistedPivotConfig(value: unknown, pivotId: string): PersistedPivotConfig {
1151:   if (!isRecord(value)
1152:     || value.schemaVersion !== 1
1153:     || value.pivotId !== pivotId
1154:     || typeof value.previousFocus !== 'string'
1155:     || !Array.isArray(value.saturatedDirections)) {
1156:     throw new Error(`Pivot config does not match the expected contract for "${pivotId}".`);
1157:   }
1158:   const saturatedDirections = value.saturatedDirections.map((direction, index) => {
1159:     if (typeof direction !== 'string' || direction.trim() === '') {
1160:       throw new Error(`Persisted saturatedDirections[${index}] is invalid.`);
1161:     }
1162:     return direction.trim();
1163:   });
1164:   const attempt = value.attempt === undefined ? 1 : value.attempt;
1165:   if (attempt !== 1 && attempt !== 2) {
1166:     throw new Error('Persisted pivot attempt must be 1 or 2.');
1167:   }
1168:   if (!isRecord(value.invariants)
1169:     || value.invariants.rounds !== attempt
1170:     || value.invariants.seats !== 3
1171:     || value.invariants.depth !== 1
1172:     || value.invariants.recursionAllowed !== false) {
1173:     throw new Error('Persisted pivot invariants do not match the one-round contract.');
1174:   }
1175:   return {
1176:     schemaVersion: 1,
1177:     pivotId,
1178:     identity: parsePersistedIdentity(value.identity),
1179:     attempt,
1180:     invariants: { rounds: attempt, seats: 3, depth: 1, recursionAllowed: false },
1181:     limits: parsePersistedLimits(value.limits),
1182:     usageAtStart: parsePersistedUsage(value.usageAtStart),
1183:     seats: parsePersistedSeats(value.seats),
