412:     || value.eventId.trim() === ''
413:     || value.pivotId !== pivotId
414:     || typeof value.occurredAtIso !== 'string'
415:     || value.occurredAtIso.trim() === ''
416:     || !isLifecycleTransition(value.lifecycle)) {
417:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
418:   }
419:   const event = parsePivotEventName(value.event);
420:   if (event === null || (event === 'pivot_failed'
421:     && (typeof value.reason !== 'string' || !PIVOT_FAILURE_REASONS.has(value.reason)))) {
422:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
423:   }
424:   const parsed: PivotEvent = {
425:     ...value,
426:     schemaVersion: 1,
427:     eventId: value.eventId.trim(),
428:     event,
429:     pivotId,
430:     occurredAtIso: value.occurredAtIso.trim(),
431:     lifecycle: value.lifecycle,
432:   };
433:   return parsed;
434: }
