436: function resolveProspectiveRealPath(path: string): string {
437:   let current = resolve(path);
438:   const missingSegments: string[] = [];
439:   while (!existsSync(current)) {
440:     const parent = dirname(current);
441:     if (parent === current) {
442:       throw new TypeError(`Unable to resolve artifact path "${path}".`);
443:     }
444:     missingSegments.unshift(current.slice(parent.length + (parent.endsWith(sep) ? 0 : 1)));
445:     current = parent;
446:   }
447:   return join(realpathSync.native(current), ...missingSegments);
448: }
