492: function normalizeSeats(seats: readonly PivotSeatMandate[]): readonly PivotSeatMandate[] {
493:   if (!Array.isArray(seats) || seats.length !== 3) {
494:     throw new TypeError('Exactly three Council seat mandates are required.');
495:   }
496:   const normalized = seats.map((seat, index) => {
497:     if (!isRecord(seat)) {
498:       throw new TypeError(`Seat at index ${index} must be an object.`);
499:     }
500:     const id = nonEmptyString(seat.id, `seats[${index}].id`);
501:     const mandate = nonEmptyString(seat.mandate, `seats[${index}].mandate`);
502:     if (id !== REQUIRED_SEAT_IDS[index]) {
503:       throw new TypeError(`Seat at index ${index} must use id "${REQUIRED_SEAT_IDS[index]}".`);
504:     }
505:     return { id, mandate };
506:   });
507:   const mandateKeys = new Set(normalized.map((seat) => normalizeTrigger(seat.mandate)));
508:   if (mandateKeys.size !== 3) {
509:     throw new TypeError('Council seat mandates must be distinct.');
510:   }
511:   return normalized;
512: }
