535: function readEventStore(statePath: string, pivotId: string): EventStore {
536:   const events: PivotEvent[] = [];
537:   const byId = new Map<string, PivotEvent>();
538:   if (!existsSync(statePath)) {
539:     return { events, byId };
540:   }
541: 
542:   const lines = readFileSync(statePath, 'utf8').split(/\r?\n/u).filter((line) => line.trim() !== '');
543:   lines.forEach((line, index) => {
544:     let parsed: unknown;
545:     try {
546:       parsed = JSON.parse(line);
547:     } catch (error: unknown) {
548:       const message = error instanceof Error ? error.message : String(error);
549:       throw new Error(`Pivot state line ${index + 1} is invalid JSON: ${message}`);
550:     }
551:     const event = parsePersistedPivotEvent(parsed, pivotId, index);
552:     const existing = byId.get(event.eventId);
553:     if (existing) {
554:       if (stableJson(eventSemanticPayload(existing)) !== stableJson(eventSemanticPayload(event))) {
555:         throw new Error(`Conflicting durable pivot event "${event.eventId}".`);
556:       }
557:       return;
558:     }
559:     events.push(event);
560:     byId.set(event.eventId, event);
561:   });
562:   return { events, byId };
563: }
