565: function appendEvent(
566:   store: EventStore,
567:   statePath: string,
568:   pivotId: string,
569:   now: () => Date | string,
570:   observer: PivotEventObserver | undefined,
571:   event: Pick<PivotEvent, 'eventId' | 'event' | 'lifecycle'> & Record<string, unknown>,
572: ): PivotEvent {
573:   const candidate: PivotEvent = {
574:     schemaVersion: 1,
575:     ...event,
576:     pivotId,
577:     occurredAtIso: isoTimestamp(now),
578:   };
579:   const existing = store.byId.get(candidate.eventId);
580:   if (existing) {
581:     if (stableJson(eventSemanticPayload(existing)) !== stableJson(eventSemanticPayload(candidate))) {
582:       throw new Error(`Conflicting replay for pivot event "${candidate.eventId}".`);
583:     }
584:     return existing;
585:   }
586: 
587:   appendJsonlIfChangedAtomic(statePath, candidate, {
588:     cache: new Map<string, string>(),
589:     diffField: 'event_hash',
590:     diffData: eventSemanticPayload(candidate),
591:   });
592:   store.events.push(candidate);
593:   store.byId.set(candidate.eventId, candidate);
594:   observer?.(candidate);
595:   return candidate;
596: }
