802: /** Derive the deterministic pivot id from immutable lineage and normalized trigger data. */
803: export function derivePivotId(input: PivotIdentityInput): string {
804:   const identity = validateIdentity(input);
805:   const digestInput = [
806:     identity.sessionId,
807:     identity.generation,
808:     identity.loopType,
809:     identity.sourceIteration,
810:     identity.normalizedTrigger,
811:   ].join('|');
812:   const digest = createHash('sha256').update(digestInput).digest('hex').slice(0, 12);
813:   return `pivot-${identity.ordinal}-${digest}`;
814: }
